    flavor:'你从没打算当英雄，事情只是恰好发生在你面前，而你是唯一没有转身的人。\n\n你熟悉谷物的价格、冬天的风，以及邻居家孩子什么时候该上学。你的勇气不是无畏，是你知道不挺身而出的代价。\n\n现在，整个镇子都在等你回来。',
