    flavor:'你在神殿的走廊里扫过很多年的地。\n\n你听过太多人对着雕像说话，多到你能从语气里听出他是来求什么。你自己也求过——求过一次，没有得到答复。\n\n但你还是留下了。因为有些工作，需要有人一直站在那儿。',
