    flavor:'东西坏了就需要有人修，而你恰好是那个人。\n\n你的手上有一层洗不掉的茧，还有几道烫出来的旧疤。你看一把椅子会先看它的接缝，听一句话会先听它有没有松动的地方。\n\n世界会坏。你的工作是让它再撑久一点。',
