/* 资源池：实际余量存在角色的 c.res[key]；上限由等级（与属性）推导。
   rec = 恢复方式：long 长休／short 短休或长休／none 不自动恢复
   pool = true 表示这是「点数额度」（如圣疗池），不是一个一个的次数 */
